// Clean every field, then say why a lead can't be used instead of dropping it silently.
const EMAIL = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i;
return $input.all().map(({ json }) => {
  const body = json.body ?? json; // the webhook wraps the form fields in body
  const name = String(body.name ?? '').replace(/\s+/g, ' ').trim();
  const email = String(body.email ?? '').trim().toLowerCase();
  const phone = String(body.phone ?? '').replace(/[^\d+]/g, '');
  const issues = [];
  if (!name) issues.push('no name');
  if (!email && !phone) issues.push('no email or phone');
  if (email && !EMAIL.test(email)) issues.push('email looks wrong');
  return { json: { name, email, phone, source: String(body.source ?? 'unknown'), message: String(body.message ?? '').trim(), valid: issues.length === 0, issues: issues.join('; ') } };
});

// Same person sent the form twice: keep the first one, matched by email (or phone when there is no email).
const seen = new Set();
return $input.all().filter(({ json }) => {
  const key = json.email || json.phone;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

// Plain rules a sales team can read and change. Score 60+ = hot, 30-59 = warm, else cold.
const money = m => { const x = m.match(/\$\s?([\d,]+)/); return x ? Number(x[1].replace(/,/g, '')) : 0; };
const URGENT = /\b(asap|urgent|today|this week|next week)\b/i;
const CALM = /\b(not urgent|no rush)\b/i;
return $input.all().map(({ json }) => {
  const budget = money(json.message);
  const why = [];
  let score = 0;
  if (budget) { score += 40; why.push('budget $' + budget.toLocaleString('en-US')); }
  if (budget >= 1000) { score += 20; why.push('budget 1,000+'); }
  if (URGENT.test(json.message) && !CALM.test(json.message)) { score += 25; why.push('wants it soon'); }
  if (json.message.length >= 60) { score += 15; why.push('detailed request'); }
  const tier = score >= 60 ? 'hot' : score >= 30 ? 'warm' : 'cold';
  return { json: { ...json, score, tier, why: why.join(', ') || 'no signals' } };
});

// One line per run for the log, and the numbers the self-test checks.
const leads = $input.all().map(i => i.json);
const count = t => leads.filter(l => l.tier === t).length;
return [{ json: { kept: leads.length, hot: count('hot'), warm: count('warm'), cold: count('cold'), leads: leads.map(l => `${l.tier.padEnd(4)} ${String(l.score).padStart(3)}  ${l.name} <${l.email || l.phone}>  ${l.why}`) } }];
